let lineThickness = 15;
let lineSpacing = 5;
let circles;
let startColor, endColor;
let bgColor;

function setup() {
	createCanvas(windowWidth, windowHeight);
	colorMode(HSB, 360, 100, 100, 100);
	startColor = color(random(360), random(100), random(100));
	endColor = color(random(360), random(100), random(100));
	bgColor = shuffle([color(32, 6, 95),color(220,50,20)])[0];
	lineThickness = floor(random(5,25));
	lineSpacing = floor(random(1,4));

	const minSide = max(windowWidth, windowHeight);
	const numberOfCircles = floor(random(6,16));

	circles = new Array(numberOfCircles).fill(0).map(() => {
		const r = (random(random(1)) * 0.9 + 0.1) * minSide * 0.5;
		const x = random(-r, width + r);
		const y = random(-r, height + r);
		const vx = randomNegator(random(0.1, 1));
		const vy = randomNegator(random(0.1, 1));
		return [x, y, r, vx, vy];
	})
}

function draw() {
	background(bgColor);
	strokeWeight(lineThickness);
	for (let y = 0; y < height; y += lineThickness + lineSpacing) {
		const t = y / height;
		const c = lerpColor(startColor, endColor, t);
		stroke(c);
		const events = getEvents(y);
		beginShape(LINES);
		events.forEach((x) => {
			vertex(x, y);
		});
		endShape();
	}

	circles = circles.map(([cx, cy, cr, vx, vy]) => {
		let nvx = vx;
		let nvy = vy;
		let nx = cx + nvx;
		let ny = cy + nvy;

		if (nx + cr < 0) {
			nx = -cr;
			nvx = -nvx;
		} else if (nx - cr > width) {
			nx = width + cr;
			nvx = -nvx;
		}
		if (ny + cr < 0) {
			ny = -cr;
			nvy = -nvy;
		} else if (ny - cr > height) {
			ny = height + cr;
			nvy = -nvy;
		}

		return [nx, ny, cr, nvx, nvy];
	})
}

function getEvents(y = 0) {
	var events = [-100, width+100];
	for (const [cx, cy, cr] of circles) {
		if (y > cy - cr && y < cy + cr) {
			const o = cy - y;
			const h = cr;
			const a = cos(asin(o / h));
			events.push(cx - a * cr);
			events.push(cx + a * cr);
		}
	}
	events.sort((a, b) => a - b);

	return events;
}

function randomNegator(value) {
	return random() > 0.5 ? value : -value;
}
